async function MAIN_LOOP() {
  let icnt = 0, ocnt = 0, num = 0, cnt = 0, obj = 0, tbl = 0, v_ = 0, ptbl = 0, obj1 = 0, tmp = 0, acted = 0;
  for (;;) {
    cnt = 0;
    obj = false;
    ptbl = true;
    acted = false;
    if (!(g.QCONTEXT_ROOM == g.HERE)) {
      g.QCONTEXT = false;
    }
    g.P_WALK_DIR = false;
    if (g.P_WON = await PARSER()) {
      g.LAST_PLAYER_LOC = loc(PLAYER);
      if (!(g.P_WON == M_FATAL)) {
        icnt = get(g.P_PRSI, g.P_MATCHLEN);
        num = (ocnt = get(g.P_PRSO, g.P_MATCHLEN)) == 0 ? ocnt : (ocnt > 1 ? (tbl = g.P_PRSO, icnt == 0 ? (obj = false) : (obj = get(g.P_PRSI, 1)), ocnt) : (icnt > 1 ? (ptbl = false, tbl = g.P_PRSI, obj = get(g.P_PRSO, 1), icnt) : 1));
        if (!obj && (icnt == 1)) {
          obj = get(g.P_PRSI, 1);
        }
      } else {
        num = 0;
      }
      if ((g.PRSA == V.WALK) && g.P_WALK_DIR) {
        v_ = await PERFORM(g.PRSA, g.PRSO);
      } else if (num == 0) {
        if ((g.PRSA == V.CONTINUE) || ((getb(g.P_SYNTAX, P_SBITS) & P_SONUMS) == 0)) {
          v_ = await PERFORM(g.PRSA);
          g.PRSO = false;
        } else {
          await TELL_NOTHING_TO();
          v_ = false;
        }
      } else if (ptbl && (num > 1) && isVerb(V.ARREST, V.COMPARE, V.EXAMINE)) {
        v_ = await PERFORM(g.PRSA, OBJECT_PAIR);
      } else {
        tmp = 0;
        loop2: for (;;) {
          if ((cnt = cnt + 1) > num) {
            if (tmp > 0) {
              tell("The other object");
              if (!(tmp == 1)) {
                tell("s");
              }
              tell(" that you mentioned ");
              if (!(tmp == 1)) {
                tell("are");
              } else {
                tell("is");
              }
              tell("n't");
              await TELL_HERE();
            } else if (!acted) {
              await TELL_NOTHING_TO();
            }
            break loop2;
          } else {
            if (ptbl) {
              obj1 = get(g.P_PRSO, cnt);
            } else {
              obj1 = get(g.P_PRSI, cnt);
            }
            if (num > 1) {
              if (obj1 == NOT_HERE_OBJECT) {
                tmp = tmp + 1;
                continue loop2;
              } else if (g.P_GETFLAGS == P_ALL) {
                if (isVerb(V.TAKE) && ((!(eq(loc(obj1), g.WINNER, g.HERE, obj)) && !(hasFlag(loc(obj1), SURFACEBIT))) || (!(hasFlag(obj1, TAKEBIT)) && !(hasFlag(obj1, TRYTAKEBIT))))) {
                  continue loop2;
                } else if (isVerb(V.TAKE) && obj && ((obj == obj1) || !(loc(obj1) == obj))) {
                  continue loop2;
                } else if (isVerb(V.DROP) && !(loc(obj1) == g.WINNER)) {
                  continue loop2;
                } else if (isVerb(V.PUT) && (await HELD$(obj1, obj))) {
                  continue loop2;
                }
              }
              if (obj1 == IT) {
                await DPRINT(g.P_IT_OBJECT);
              } else {
                await DPRINT(obj1);
              }
              tell(": ");
            }
            v_ = await QCONTEXT_CHECK(ptbl ? obj1 : obj, ptbl ? obj : obj1);
            acted = true;
            v_ = await PERFORM(g.PRSA, ptbl ? obj1 : obj, ptbl ? obj : obj1);
            if (v_ == M_FATAL) {
              break loop2;
            }
          }
        }
      }
      if (v_ == M_FATAL) {
        g.P_CONT = false;
      }
    } else {
      g.P_CONT = false;
    }
    if (g.P_WON) {
      if (isVerb(V.TELL, V.BRIEF, V.SUPER_BRIEF, V.VERBOSE, V.SAVE, V.RESTORE, V.RESTART, V.SPACE, V.UNSPACE, V.SCRIPT, V.UNSCRIPT, V.VERSION, V.SCORE, V.TIME, V.$VERIFY)) {
      } else {
        v_ = await CLOCKER();
      }
    }
  }
}

