async function QCONTEXT_CHECK(prso, prsi) {
  let other = 0, who = false, n_ = 0;
  if (isVerb(V.TELL)) {
    return false;
  } else if (isVerb(V.HELP, V.WHAT) || (isVerb(V.TELL_ME) && (prso == PLAYER || prso == ME)) || (isVerb(V.SHOW, V.GIVE) && (prsi == PLAYER || prsi == ME))) {
    other = first(g.HERE);
    loop1: for (;;) {
      if (!other) {
        break loop1;
      } else if (hasFlag(other, PERSON)) {
        n_ = 1 + n_;
        who = other;
      }
      other = next(other);
    }
    if ((1 == n_) && !g.QCONTEXT) {
      await SAID_TO(who);
    }
    if (g.QCONTEXT && (loc(g.QCONTEXT) == g.HERE) && (g.QCONTEXT_ROOM == g.HERE) && (g.WINNER == PLAYER)) {
      g.WINNER = g.QCONTEXT;
      tell("(said to ");
      await DPRINT(g.QCONTEXT);
      tell(")\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

