async function DIR_FROM(here, there) {
  let p_ = 0, l = 0, t = 0, o = 0;
  for (;;) {
    if ((p_ = nextProp(here, p_)) == 0) {
      return false;
    } else if (p_ == P.IN || p_ == P.OUT) {
    } else if (!(p_ < LOW_DIRECTION)) {
      t = getPropAddr(here, p_);
      l = propSize(t);
      if ((l == DEXIT || l == UEXIT || l == CEXIT) && eq(getb(t, REXIT), there)) {
        return p_;
      }
    }
  }
}

