async function V_WAIT(num = 10, who = false, int = false) {
  let val = 0, hr = 0, result = true;
  hr = g.HERE;
  g.WHO_WAIT = 0;
  if (!int) {
    tell("Time passes...\n");
  }
  loop1: for (;;) {
    if ((num = num - 1) < 0) {
      break loop1;
    } else if (val = await CLOCKER()) {
      if ((val == M_FATAL) || !(hr == g.HERE)) {
        result = M_FATAL;
        break loop1;
      } else if (who && (loc(who) == g.HERE)) {
        await DPRINT(who, true);
        tell(", for whom you are waiting, has arrived.\n");
        break loop1;
      } else {
        g.WHO_WAIT = g.WHO_WAIT + 1;
        if (!(eq(getb(0, 1) & 16, 0))) {
          tell("(");
          await TIME_PRINT(g.PRESENT_TIME);
          tell(") ");
        }
        tell(S(g.DO_YOU_WANT_TO));
        if (int) {
          tell("continue what you were doing?");
        } else {
          tell("keep waiting?");
        }
        if (!(await YES$())) {
          result = false;
          break loop1;
        } else {
        }
      }
    } else if (who && (loc(who) == g.HERE)) {
      await DPRINT(who, true);
      tell(", for whom you are waiting, has arrived.\n");
      break loop1;
    } else if (who && ((g.WHO_WAIT = g.WHO_WAIT + 1) > 40)) {
      await DPRINT(who, true);
      tell(" still hasn't arrived.  ", S(g.DO_YOU_WANT_TO), "keep waiting?");
      if (!(await YES$())) {
        result = false;
        break loop1;
      }
      g.WHO_WAIT = 0;
    } else {
    }
  }
  g.CLOCK_WAIT = true;
  if (!int) {
    await V_TIME();
  }
  return result;
}

async function INT_WAIT(n_) {
  return await V_WAIT(n_ * 2, false, true);
}

async function V_WAIT_FOR() {
  let who = 0;
  if (g.PRSO == INTNUM) {
    if (g.P_NUMBER > g.PRESENT_TIME) {
      await V_WAIT_UNTIL();
      return true;
    } else if (g.P_NUMBER > 180) {
      tell("That's too long to wait.\n");
      return true;
    } else {
      return await V_WAIT(g.P_NUMBER);
    }
  } else if (g.PRSO == GLOBAL_HERE) {
    await V_WAIT();
    return true;
  } else if (g.PRSO == MIDNIGHT) {
    await V_WAIT_UNTIL();
    return true;
  } else if (hasFlag(g.PRSO, PERSON)) {
    if (who = await CHARACTERIZE$(g.PRSO)) {
      if (loc(who) == g.HERE) {
        tell("That person's", S(g.ALREADY_HERE), "\n");
        return true;
      } else {
        return await V_WAIT(10000, who);
      }
    } else {
      tell("You would be better off not waiting.\n");
      return true;
    }
  } else if (g.PRSO == PLAYER) {
    tell("You're", S(g.ALREADY_HERE), "\n");
    return true;
  } else {
    tell("Not a good idea. You might wait all night.\n");
    return true;
  }
}

async function V_WAIT_UNTIL() {
  if (g.PRSO == MIDNIGHT) {
    g.P_NUMBER = 720;
    g.PRSO = INTNUM;
  } else if (g.P_NUMBER < 8) {
    g.P_NUMBER = (g.P_NUMBER + 12) * 60;
  } else if (g.P_NUMBER < 13) {
    g.P_NUMBER = g.P_NUMBER * 60;
  }
  if (g.PRSO == INTNUM) {
    if (g.P_NUMBER > g.PRESENT_TIME) {
      return await V_WAIT(g.P_NUMBER - g.PRESENT_TIME);
    } else {
      tell(S(g.YOU_ARE), "clearly ahead of your time.\n");
      return true;
    }
  } else {
    tell("It has been a long week, hasn't it?\n");
    return true;
  }
}

