async function V_WALK() {
  let pt = 0, pts = 0, str = 0, obj = 0, rm = 0;
  if (g.WINNER == PLAYER) {
    put(get(g.GOAL_TABLES, PLAYER_C), GOAL_S, false);
  }
  if (!g.PRSO) {
    return await TELL_YOU_CANT(g.GO_THAT_WAY);
  } else if (pt = getPropAddr(g.HERE, g.PRSO)) {
    g.P_WALK_DIR = g.PRSO;
    if (eq(pts = propSize(pt), UEXIT)) {
      rm = getb(pt, REXIT);
      return await GOTO(rm);
    } else if (pts == NEXIT) {
      tell(S(get(pt, NEXITSTR)), "\n");
      return M_FATAL;
    } else if (pts == FEXIT) {
      if (rm = await apply(get(pt, FEXITFCN))) {
        return await GOTO(rm);
      } else {
        return M_FATAL;
      }
    } else if (pts == CEXIT) {
      if (globalValue(getb(pt, CEXITFLAG))) {
        return await GOTO(getb(pt, REXIT));
      } else if (str = get(pt, CEXITSTR)) {
        tell(S(str), "\n");
        return M_FATAL;
      } else {
        await TELL_YOU_CANT(g.GO_THAT_WAY);
        return M_FATAL;
      }
    } else if (pts == DEXIT) {
      obj = getb(pt, DEXITOBJ);
      if (hasFlag(obj, OPENBIT)) {
        return await GOTO(getb(pt, REXIT));
      } else if (!(hasFlag(obj, LOCKED))) {
        await OPEN_DOOR(obj);
        return await GOTO(getb(pt, REXIT));
      } else if (eq(getProp(obj, P.UNLOCK), g.HERE)) {
        return await TELL_UNLOCK_IT(obj);
      } else if (hasFlag(obj, INVISIBLE)) {
        return await TELL_YOU_CANT(g.GO_THAT_WAY);
      } else if (str = get(pt, DEXITSTR)) {
        tell(S(str), "\n");
        return M_FATAL;
      } else {
        tell(S(g.TOO_BAD));
        await THE_PRINT(obj);
        tell(" is locked.\n");
        await THIS_IS_IT(obj);
        return M_FATAL;
      }
    } else {
      return false;
    }
  } else if (g.PRSO == P.IN) {
    tell("What compass direction do you want to go in?\n");
    return M_FATAL;
  } else {
    await TELL_YOU_CANT(g.GO_THAT_WAY);
    return M_FATAL;
  }
}

