async function V_WALK_TO() {
  let who = 0, rm = 0;
  if (g.DUFFY_SNARFED) {
    await IRON_GRIP();
    return true;
  } else if (hasFlag(g.PRSO, DOORBIT) && (rm = getProp(g.PRSO, P.UNLOCK)) && !(rm == ROOMS)) {
    g.PRSO = rm;
    return await V_THROUGH();
  } else if (eq(await META_LOC(g.PRSO), g.HERE) || (await GLOBAL_IN$(g.PRSO, g.HERE))) {
    return await TELL_CLOSE_ENOUGH();
  } else if ((loc(g.PRSO) == GLOBAL_OBJECTS) && hasFlag(g.PRSO, PERSON)) {
    who = await CHARACTERIZE(g.PRSO);
    if (await NEARBY$(who)) {
      g.PRSO = await META_LOC(who);
      return await V_THROUGH();
    } else {
      (await TELL_YOU_CANT("even see ", false));
      await DPRINT(g.PRSO);
      tell("!\n");
      return true;
    }
  } else if (g.PRSO == HALLWAY) {
    g.PRSO = HALL;
    return await V_THROUGH();
  } else if (loc(await META_LOC(g.PRSO)) == ROOMS) {
    g.PRSO = await META_LOC(g.PRSO);
    return await V_THROUGH();
  } else {
    return (await TELL_YOU_CANT("go from here to there, at least not directly"));
  }
}

