async function NEW_ARRIVAL_STUFF(who) {
  let l = 0, flg = false, det$ = false, ali$ = false, pla$ = false;
  if (g.NEW_ARRIVAL) {
    clearFlag(FRONT_DOOR, LOCKED);
    if ((g.HERE == PORCH) && !g.PLAYER_HIDING) {
      pla$ = true;
      g.NEW_ARRIVAL = PLAYER;
      await MOVE_PLAYER(HALL);
    }
    if (loc(ALICIA) == PORCH) {
      ali$ = true;
      g.NEW_ARRIVAL = ALICIA;
      move(ALICIA, HALL);
      await ESTABLISH_GOAL(ALICIA, BALLROOM_5);
    }
    if (loc(DETECTIVE) == PORCH) {
      det$ = true;
      g.NEW_ARRIVAL = DETECTIVE;
      move(DETECTIVE, HALL);
      move(DUFFY, HALL);
      await NEW_SCRIPT(DETECTIVE, g.DETECTIVE_SCRIPT);
      await NEW_SCRIPT(DUFFY, g.DUFFY_SCRIPT);
    }
    if (who == PLAYER) {
      flg = true;
      if (det$) {
        await THE_PRINT(DETECTIVE, true);
        tell(" enters the house, looking about cautiously. A few curt words of greeting are uttered.");
        await TELL_ABOUT_DUFFY();
      }
      if (ali$) {
        await ALICIA_DESC_F();
        tell(D(ALICIA), " enters the house, thanking you for answering the doorbell.\n");
        await WHERE_UPDATE(ALICIA, true);
      }
    } else {
      l = loc(BUTLER);
      if ((l == HALL || l == PORCH) && (g.HERE == HALL || g.HERE == PORCH)) {
        flg = true;
        tell(D(BUTLER), " opens the front door.");
        if (pla$) {
          tell(" He ushers you into the hall. It is clear from his demeanor that he remembers letting you in earlier in the evening, but he suppresses his perplexity reasonably well.");
        }
        if (ali$ || det$) {
          tell(" He greets ");
          if (ali$ && det$) {
            tell("everyone");
          } else {
            await DPRINT(g.NEW_ARRIVAL);
          }
          tell(", his gorilla costume eliciting a glance of suppressed amusement, and ushers the new arrival into the front hall.");
        }
        if (det$) {
          await TELL_ABOUT_DUFFY();
        } else {
          crlf();
        }
        if (ali$) {
          await WHERE_UPDATE(ALICIA, true);
        }
      }
    }
    g.NEW_ARRIVAL = false;
    return flg;
  } else {
    return false;
  }
}

