async function WINDOW_SEAT_F(rarg = false) {
  if (rarg == M_BEG) {
    if (isVerb(V.STAND, V.DISEMBARK) && (loc(g.WINNER) == WINDOW_SEAT) && g.PLAYER_HIDING) {
      setFlag(WINDOW_SEAT, OPENBIT);
      return false;
    } else if (isVerb(V.LOOK, V.EXAMINE) && g.PLAYER_HIDING) {
      (await TELL_CANT_SEE("because you're hiding!"));
      return crlf();
    } else if (isVerb(V.LOOK_INSIDE) && g.PLAYER_HIDING) {
      tell("There isn't much to see.\n");
      return true;
    } else {
      return false;
    }
  } else if (rarg) {
    return false;
  } else if (isVerb(V.OPEN)) {
    if ((loc(g.WINNER) == WINDOW_SEAT) && hasFlag(WINDOW_SEAT, SURFACEBIT)) {
      return await TELL_GET_UP();
    } else {
      clearFlag(g.PRSO, SURFACEBIT);
      if (g.PLAYER_HIDING) {
        await PLAYER_EMERGES();
      }
      return false;
    }
  } else if (isVerb(V.CLOSE) && hasFlag(g.PRSO, OPENBIT)) {
    setFlag(g.PRSO, SURFACEBIT);
    clearFlag(g.PRSO, OPENBIT);
    tell("Closed.\n");
    return true;
  } else if (isVerb(V.SIT) && hasFlag(g.PRSO, OPENBIT)) {
    (await TELL_YOU_CANT("sit on an open ", false));
    await DPRINT(g.PRSO);
    tell(".\n");
    return true;
  } else if (isVerb(V.THROUGH, V.HIDE_INSIDE)) {
    if (!(hasFlag(g.PRSO, OPENBIT))) {
      (await TELL_YOU_CANT("get in a closed ", false));
      await DPRINT(g.PRSO);
      tell(".\n");
      return true;
    } else if (loc(CORPSE) == WINDOW_SEAT) {
      tell("That would be too crowded for comfort.\n");
      return true;
    } else if (!g.PLAYER_HIDING) {
      clearFlag(WINDOW_SEAT, OPENBIT);
      move(PLAYER, WINDOW_SEAT);
      g.PLAYER_HIDING = WINDOW_SEAT;
      tell(S(g.YOU_ARE), "now hiding in the ", D(WINDOW_SEAT), ".\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.PUT) && g.PRSI && !(hasFlag(g.PRSI, OPENBIT))) {
    tell(S(g.YOU_MUST), "open the ", D(WINDOW_SEAT), " first.\n");
    return true;
  } else if (isVerb(V.PUT) && (g.PRSO == CORPSE)) {
    tell("Your name wouldn't be Brewster, by any chance?\n");
    return false;
  } else if (isVerb(V.EXAMINE)) {
    tell("A ", D(WINDOW_SEAT), " is a bench underneath a window that often has storage space inside it. This one overlooks the front of the house and down the hill. In \"Arsenic and Old Lace,\" there were several bodies hidden in ");
    await PRINTA(WINDOW_SEAT);
    tell(".\n");
    return true;
  } else {
    return false;
  }
}

