async function WHO_DERE(rm) {
  let f = 0, ch$ = 0;
  if (!(rm == g.HERE)) {
    f = first(rm);
    for (;;) {
      if (!f) {
        if (ch$ > 1) {
          tell("are");
        } else if (ch$ == 1) {
          tell("is");
        } else {
          return true;
        }
        tell(" ", S(getProp(rm, P.FDESC)), ".");
        return true;
      } else if (hasFlag(f, PERSON) && !(f == LOCAL_BAND)) {
        if (ch$ == 0) {
          tell(" ");
        } else {
          tell("and ");
        }
        if (ch$ == 0) {
          await DPRINT(f, true);
          tell(" ");
        } else {
          await DPRINT(f);
          tell(" ");
        }
        ch$ = ch$ + 1;
      }
      f = next(f);
    }
  } else {
    return false;
  }
}

async function I_MUSIC() {
  let minutes = 0, ib$ = (await IN_BALLROOM$(g.WINNER));
  if (g.PARTY_OVER) {
    g.BAND_PLAYING$ = false;
    g.RECORD_PLAYING$ = false;
    return false;
  }
  enable(await QUEUE(I_MUSIC.id, 10));
  minutes = mod(g.PRESENT_TIME, 60);
  if ((minutes > 45) || (g.PRESENT_TIME > 764)) {
    g.RECORD_PLAYING$ = await PICK_ONE(g.RECORDS);
    if (g.BAND_PLAYING$) {
      if (g.PRESENT_TIME > 764) {
        move(LOCAL_BAND, GLOBAL_OBJECTS);
      } else {
        move(LOCAL_BAND, KITCHEN);
      }
      g.BAND_PLAYING$ = false;
      if (ib$) {
        tell("The band is ", S((g.PRESENT_TIME > 764 ? "going home" : "starting its break")), " now, but to fill the gap, ");
        await PRINTA(RECORD_PLAYER);
        tell(" has been started. It's playing \"", S(g.RECORD_PLAYING$), ".\"\n");
      }
    } else if (ib$) {
      tell("The record changes. It's now playing \"", S(g.RECORD_PLAYING$), ".\"\n");
    }
  } else {
    g.BAND_PLAYING$ = await PICK_ONE(g.TUNES);
    if (g.RECORD_PLAYING$) {
      move(LOCAL_BAND, BALLROOM_2);
      g.RECORD_PLAYING$ = false;
      if (ib$) {
        tell("The band has returned from its break. They start their new set with \"", S(g.BAND_PLAYING$), ".\"\n");
      }
    } else if (ib$) {
      tell("After a short pause, the band begins to play \"", S(g.BAND_PLAYING$), ".\"\n");
    }
  }
  return false;
}

