async function GLOBAL_PERSON_F() {
  let per = 0;
  if (isVerb(V.$CALL)) {
    per = await CHARACTERIZE(g.PRSO);
    if (await NEARBY$(per)) {
      await PERFORM(V.$CALL, per);
      return true;
    } else {
      return await TELL_ISNT_HERE(per);
    }
  } else if (isVerb(V.GIVE)) {
    return await TELL_ISNT_HERE(g.PRSI);
  } else if (isVerb(V.SLAP, V.MUNG, V.KILL, V.ATTACK, V.DANCE, V.HELP, V.ACCUSE, V.SEARCH, V.LOOK_INSIDE)) {
    return await TELL_ISNT_HERE(g.PRSO);
  } else if ((isVerb(V.SHOW, V.REVEAL) && (loc(g.PRSI) == GLOBAL_OBJECTS) && (per = g.PRSI)) || (isVerb(V.ASK_ABOUT, V.TELL_ME) && (loc(g.PRSO) == GLOBAL_OBJECTS) && (per = g.PRSO))) {
    if (per == ME) {
      return false;
    } else if (await NEARBY$(per)) {
      await DPRINT(per, true);
      tell(" is waiting for you to come justify your interruption.\n");
      return true;
    } else {
      tell("Your audience isn't listening.\n");
      return true;
    }
  } else {
    return false;
  }
}

