async function PLAYER_F() {
  if (g.WINNER == PLAYER) {
    if (isVerb(V.EXAMINE) && (g.PRSO == PLAYER)) {
      tell("You look pretty much like you always do, excepting the fact that you are wearing a fairly ridiculous looking ", D(COWBOY_COSTUME), ".\n");
      return true;
    } else if (NOT_ROPE == g.PRSO || NOT_ROPE == g.PRSI) {
      return await NOT_ROPE_F();
    } else if (isVerb(V.ACCUSE, V.ARREST) && (g.PRSO == PLAYER || g.PRSO == ME)) {
      tell("Turning yourself in, eh?\n");
      return true;
    } else if (isVerb(V.KILL, V.ATTACK) && (loc(g.PRSO) == g.HERE) && !(g.PRSO == CORPSE || g.PRSO == VERONICA || g.PRSO == DOG)) {
      if (g.PRSO == PLAYER) {
        tell("Suicide");
      } else if (hasFlag(g.PRSO, PERSON)) {
        tell(S((hasFlag(PLAYER, TOLD) ? "Another " : "A ")), D(GLOBAL_MURDER));
      } else {
        tell("This");
      }
      tell(" is not the way to clear up this mess.\n");
      return true;
    } else if (isVerb(V.GIVE) && (g.PRSI == PLAYER)) {
      tell("Taking up juggling, eh?\n");
      return true;
    } else if (isVerb(V.TAKE, V.DANCE) && (g.PRSO == PLAYER)) {
      tell("Usually, you say that to someone else.\n");
      return true;
    } else if ((loc(DETECTIVE) == g.HERE) && (g.TARGET == PLAYER)) {
      if (isVerb(V.SSHOW, V.SGIVE)) {
        return false;
      } else if ((await PLAYER_ARRESTED$(DETECTIVE)) && isVerb(V.WALK, V.WALK_TO, V.FOLLOW, V.THROUGH)) {
        return true;
      } else {
        return false;
      }
    } else if ((loc(DETECTIVE) == g.HERE) && (await LAB_RESULTS_TO_PLAYER())) {
      crlf();
      return false;
    } else if ((loc(DUFFY) == g.HERE) && (g.TARGET == PLAYER)) {
      if (isVerb(V.SSHOW, V.SGIVE)) {
        return false;
      } else if ((await PLAYER_ARRESTED$(DUFFY)) && isVerb(V.WALK, V.WALK_TO, V.FOLLOW, V.THROUGH)) {
        return true;
      } else {
        return false;
      }
    } else if ((isVerb(V.REVEAL) && (g.PRSI == PLAYER)) || (isVerb(V.TELL_ME, V.TELL, V.$CALL) && (g.PRSO == PLAYER))) {
      if (isVerb(V.TELL)) {
        g.P_CONT = false;
        g.QUOTE_FLAG = false;
      }
      return await INTERVIEW_SELF();
    } else if ((isVerb(V.REVEAL) && (g.PRSO == GLOBAL_MURDER)) || (isVerb(V.TELL_ME, V.ASK_ABOUT) && (g.PRSI == GLOBAL_MURDER))) {
      if (!(hasFlag(PLAYER, TOLD))) {
        tell("What murder? ", S(g.YOU_DONT), "know anything about a murder.\n");
        return true;
      } else {
        return false;
      }
    } else if ((isVerb(V.THROW_AT, V.POUR_ON) && (g.PRSI == PLAYER)) || (isVerb(V.RUB, V.FOLLOW) && (g.PRSO == PLAYER))) {
      tell(S(g.YOU_ARENT), "coordinated enough.\n");
      return true;
    } else if (isVerb(V.ALARM) && (g.PRSO == false || g.PRSO == PLAYER || g.PRSO == ME)) {
      tell("Getting sleepy, huh?\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

