async function REVEAL_MURDER(who) {
  let n_ = 0, x = 0, news$ = !(hasFlag(who, TOLD));
  if (news$) {
    setFlag(who, TOLD);
  }
  x = first(loc(who));
  loop1: for (;;) {
    if (!x) {
      break loop1;
    }
    n_ = next(x);
    if (hasFlag(x, PERSON) && !(hasFlag(x, TOLD))) {
      setFlag(x, TOLD);
    }
    x = n_;
  }
  if (!g.MURDER_PUBLIC$) {
    g.MURDER_PUBLIC$ = who;
    setFlag(DETECTIVE, TOLD);
    setFlag(DUFFY, TOLD);
    enable(await QUEUE(I_POLICE_ARRIVE.id, 25));
  }
  return news$;
}

