async function BUTLER_F() {
  if (g.WINNER == BUTLER) {
    if (g.ENTANGLED$) {
      tell(D(BUTLER), " is in no condition to talk now.\n");
      return true;
    } else if (isVerb(V.HELLO)) {
      tell("\"How do you do? A lovely evening, isn't it?\"\n");
      return true;
    } else if (isVerb(V.GIVE)) {
      if (g.PRSO == GLASS) {
        tell("\"I'm sorry, but you might cut yourself. I propose to throw this in the trash.\"\n");
        return true;
      } else if (g.PRSI == PLAYER) {
        move(g.PRSO, g.PRSI);
        tell("\"If you insist,\" he replies, handing you ");
        return await TELL_PRSO();
      } else {
        tell("He politely refuses.\n");
        return true;
      }
    } else if (await DONT_HANDLE$()) {
      return false;
    } else {
      tell(D(BUTLER), " looks at you calmly through the eyeholes of his gorilla suit.\n");
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    tell("George ", D(BUTLER), ", the butler, is resplendent in an all-over gorilla suit, over which he is wearing his butler's uniform (up to and including white gloves). The effect is striking, particularly when he speaks, as ", D(BUTLER), " has a British accent.\n");
    return true;
  } else if (isVerb(V.DANCE)) {
    tell("\"I beg your pardon? I'm working, as you can see.\"\n");
    return true;
  } else if (isVerb(V.REVEAL) && (g.PRSO == GLOBAL_MURDER)) {
    if (await REVEAL_MURDER(BUTLER)) {
      tell("\"A tragedy.\" He seems to be genuinely saddened by the news.\n");
      return true;
    } else {
      tell("\"It is extremely improper of you to be conveying this news in such a callous way.\"\n");
      return true;
    }
  } else if (isVerb(V.GIVE)) {
    if (g.PRSO == YOUR_COAT || g.PRSO == ALICIA_COAT) {
      move(g.PRSO, BUTLER);
      await NEW_SCRIPT(BUTLER, g.BUTLER_LOOP);
      if (loc(BUTLER) == g.HERE) {
        if (!(g.WINNER == PLAYER)) {
          await DPRINT(g.WINNER, true);
          tell(" gives ");
          await HIM_HER_PRINT(g.WINNER, true);
          tell(" coat to the butler.\n");
        }
        tell("\"Thank you, I'll go hang it up. I believe you know your way to the ballroom? It's down the long hall to the right. I hope you enjoy your evening.\"\n");
      }
    } else if (g.PRSO == GLASS) {
      move(GLASS, BUTLER);
      await ESTABLISH_GOAL(BUTLER, KITCHEN, true);
      tell("The butler takes it carefully. \"You could have cut yourself,\" he comments.\n");
    } else if (loc(BUTLER) == g.HERE) {
      tell("The butler politely refuses ");
      await TELL_PRSO();
    }
    return true;
  } else if (isVerb(V.ASK_ABOUT) && (g.PRSO == BUTLER)) {
    tell(D(BUTLER), " ignores the question.\n");
    return true;
  } else {
    return false;
  }
}

async function G_BUTLER(garg) {
  let na = false, ow = 0, coat = 0, l = loc(BUTLER), flg = false, here$ = (g.HERE == l);
  ow = g.WINNER;
  if (!garg) {
    return await IMOVEMENT(BUTLER, G_BUTLER.id);
  } else if (garg == G_IMPATIENT) {
    tell("\"Pardon me,\" says ", D(BUTLER), ", \"but I have work to do.\"\n");
    return true;
  } else if (garg == G_ENROUTE) {
    if (!g.NEW_ARRIVAL) {
      if (loc(ALICIA) == l) {
        na = ALICIA;
        coat = ALICIA_COAT;
      } else if (loc(DETECTIVE) == l) {
        na = DETECTIVE;
        coat = DETECTIVE_COAT;
      } else if (loc(DUFFY) == l) {
        na = DUFFY;
        coat = DUFFY_COAT;
      } else if (eq(await META_LOC(PLAYER), l)) {
        na = PLAYER;
        coat = YOUR_COAT;
      }
      if (na) {
        if ((loc(coat) == na) && !(hasFlag(coat, RMUNGBIT))) {
          setFlag(coat, RMUNGBIT);
          if (here$) {
            tell(D(BUTLER), " says to ");
            if (na == PLAYER) {
              tell("you");
            } else {
              await DPRINT(na);
            }
            tell(", \"If you would be so kind as to give me your coat, I'll hang it up for you.\"\n");
          }
          if (!(na == PLAYER)) {
            g.WINNER = na;
            await PERFORM(V.GIVE, coat, BUTLER);
            g.WINNER = ow;
          }
        }
        return here$;
      }
      if ((loc(GLASS) == BALLROOM_8) && !(await IN_MOTION$(VERONICA))) {
        await ESTABLISH_GOAL(BUTLER, BALLROOM_8, true);
        return false;
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else if (garg == G_REACHED || garg == G_ALREADY) {
    await UNPRIORITIZE(BUTLER);
    if (loc(BUTLER) == HALL) {
      if (g.NEW_ARRIVAL) {
        flg = await NEW_ARRIVAL_STUFF(BUTLER);
      } else if (g.HERE == HALL) {
        flg = true;
        tell("The butler looks out the ", D(FRONT_DOOR), ", finds no one waiting, and resumes his regular rounds.\n");
      }
      await NEW_SCRIPT(BUTLER, g.BUTLER_LOOP);
      return flg;
    } else if (loc(BUTLER) == EAST_COAT_CLOSET) {
      if (await DUMP_COATS()) {
        if (here$) {
          tell(D(BUTLER), " hangs the coat in the closet.\n");
          return true;
        } else {
          return false;
        }
      } else {
        return false;
      }
    } else if (l == BALLROOM_8) {
      if (loc(GLASS) == BALLROOM_8) {
        move(GLASS, BUTLER);
        await ESTABLISH_GOAL(BUTLER, KITCHEN, true);
        if (await IN_BALLROOM$(PLAYER)) {
          tell(D(BUTLER), " unobtrusively sweeps up ");
          await THE_PRINT(GLASS);
          tell(".\n");
          return true;
        } else {
          return false;
        }
      } else {
        return false;
      }
    } else if ((l == KITCHEN) && (loc(GLASS) == BUTLER)) {
      if (g.HERE == KITCHEN) {
        tell(D(BUTLER), " dumps ");
        await THE_PRINT(GLASS);
        tell(" in ");
      }
      if (loc(TRASH_BASKET) == KITCHEN) {
        move(GLASS, TRASH_BASKET);
        if (g.HERE == KITCHEN) {
          await THE_PRINT(TRASH_BASKET);
          tell(".\n");
          return true;
        } else {
          return false;
        }
      } else {
        remove(GLASS);
        if (g.HERE == KITCHEN) {
          tell("the garbage disposal.\n");
          return true;
        } else {
          return false;
        }
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function DUMP_COATS() {
  let n_ = 0, x = 0, robbed$ = false;
  x = first(BUTLER);
  for (;;) {
    if (!x) {
      return robbed$;
    }
    n_ = next(x);
    if (hasFlag(x, TAKEBIT) && !(x == GLASS)) {
      move(x, EAST_COAT_CLOSET);
      clearFlag(x, NDESCBIT);
      robbed$ = x;
    }
    x = n_;
  }
}

async function TRASH_BASKET_F() {
  if (isVerb(V.LOOK_INSIDE, V.EXAMINE, V.SEARCH)) {
    if (loc(GLASS) == TRASH_BASKET) {
      tell("A ", D(GLASS), " is on top");
    } else {
      tell("It's nearly full");
    }
    tell(" of uninteresting garbage");
    (await PRINT_CONTENTS(TRASH_BASKET, ", including ", GLASS));
    tell(".\n");
    return true;
  } else {
    return false;
  }
}

async function BARTENDER_F() {
  let ow = 0;
  ow = g.WINNER;
  if (g.WINNER == BARTENDER) {
    if (isVerb(V.HELLO)) {
      tell(S(g.HEY_BARTENDER), "\n");
      return true;
    } else if (isVerb(V.GIVE, V.MAKE)) {
      if (!g.PRSI) {
        return false;
      } else if ((g.PRSO == DRINK || g.PRSO == GLOBAL_DRINK) || (g.PRSI == DRINK || g.PRSI == GLOBAL_DRINK)) {
        if ((g.PRSI == ME || g.PRSI == PLAYER) || (g.PRSO == ME || g.PRSO == PLAYER)) {
          g.DRINK_COUNT = g.DRINK_COUNT + 1;
          tell("\"Sure.");
          if (loc(DRINK) == PLAYER) {
            tell(" Here, let me take your old one.");
          }
          await THIS_IS_IT(DRINK);
          move(DRINK, PLAYER);
          putProp(DRINK, P.SIZE, 10);
          if (g.DRINK_COUNT > 3) {
            tell(" Don't you think you've had enough?\"\n");
            return true;
          } else {
            tell("\" The bartender swiftly and efficiently mixes a drink, then hands it to you.\n");
            return true;
          }
        } else if (hasFlag(g.PRSO, PERSON) || hasFlag(g.PRSI, PERSON)) {
          tell("\"", S(g.YOU_SHOULD), "let people order their own drinks.\"\n");
          return true;
        } else {
          tell("\"Pardon?\"\n");
          return true;
        }
      } else {
        tell("\"I'm afraid I can't make one of those.\"\n");
        return true;
      }
    } else if (await DONT_HANDLE$()) {
      return false;
    } else {
      tell("\"Sorry, I've been hired to mix drinks and that's all I'll do.\"\n");
      return true;
    }
  } else if (isVerb(V.HELLO)) {
    tell(S(g.HEY_BARTENDER), "\n");
    return true;
  } else if (isVerb(V.TIP)) {
    tell("\"Thanks.\"\n");
    return true;
  } else if (isVerb(V.ASK_FOR)) {
    if (g.PRSI == DRINK || g.PRSI == GLOBAL_DRINK) {
      g.WINNER = BARTENDER;
      await PERFORM(V.GIVE, DRINK, PLAYER);
      g.WINNER = ow;
      return true;
    } else {
      tell("\"I don't have that.\"\n");
      return true;
    }
  } else if (isVerb(V.REVEAL) && (g.PRSO == GLOBAL_MURDER)) {
    if (await REVEAL_MURDER(BARTENDER)) {
      tell("\"I hope I'll still get paid.\" He realizes that wasn't a very tactful remark, and tries to recover. \"It's too bad.\"\n");
      return true;
    } else {
      tell("\"I know. You'd think it would quiet these people down, but it hasn't.\"\n");
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    tell("Jack Johnson, the bartender, is a well-barbered young man wearing a red uniform and, as his only concession to the theme of the party, a simple domino mask.\n");
    return true;
  } else if (isVerb(V.DANCE)) {
    tell("\"Sorry, I'm on duty.\"\n");
    return true;
  } else if (isVerb(V.ASK_ABOUT) && (g.PRSO == BARTENDER)) {
    if (g.PRSI == DRINK || g.PRSI == GLOBAL_DRINK || g.PRSI == BAR) {
      tell("\"I know a lot about drinks.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_MURDER) {
      if (hasFlag(g.PRSO, TOLD)) {
        tell("\"It certainly puts a damper on the evening for me, but no one else seems too concerned.\"\n");
        return true;
      } else {
        tell("\"What? What murder?\"\n");
        return true;
      }
    } else if (g.PRSI == PLAYER) {
      tell("\"I'm interested in things like libel law, and the first amendment. We should talk later, I'm sure your views are interesting.\"\n");
      return true;
    } else if (g.PRSI == BARTENDER) {
      tell("\"I'm Jack Johnson. I'm trying to pay some of my tuition by working behind bars. Get it? Well, I get quite a view of mankind. It's good practice, I'm going to be a lawyer.\"\n");
      return true;
    } else if (loc(g.PRSI) == g.HERE) {
      tell("Glancing discreetly at the subject of the inquiry, Jack only smiles.\n");
      return true;
    } else if (g.PRSI == GLOBAL_MICHAEL) {
      tell("\"Nice guy, sort of the hail-fellow-well-met type. Practically broke my hand shaking it when I first came in. Likes a very dry martini, already had a couple tonight. 'You want dry?' I told him. I pour the gin in, and then I kinda wave the fumes from the vermouth over the glass. He thought that was a good one...\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_VERONICA) {
      tell("\"One of her friends told her about me. I worked a party over there a month or so ago, so Ms. Ashcroft asks the agency for me specifically. I can use the dough. Going to Law School, and it ain't cheap.\" He looks significantly at the tip glass. \"Anyway, she had a Singapore Sling: most of these women like a sweet drink.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_LINDA) {
      tell("\"A knockout, isn't she? She actually drinks sloe gin fizzes. I didn't think anybody over 21 could stand them.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_RICHARD) {
      tell("\"He seems sort of beaten down. You see too many of them in this business. Like they're carrying something too heavy.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_COL_MARSTON) {
      tell("\"A very distinguished gentleman, and he knows it. Of course, the fact that he knows it spoils the whole effect.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_ALICIA) {
      if (g.ALICIA_HERE$) {
        tell("\"Nice harem costume.\"\n");
        return true;
      } else {
        tell("\"I haven't seen her.\"\n");
        return true;
      }
    } else if (g.PRSI == GLOBAL_SEN_ASHER) {
      tell("\"The man's a true politician. Not even up for election for another four years, and he's doing the whole campaign bit the first time he comes over for a drink. Of course, I guess I'm the closest thing there is to the public here, the average income in this room must be something. He told me he's a teetotaler, too: ordered a soft drink. His father was an alcoholic and the Senator could never bring himself to drink, remembering.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_COCHRANE) {
      tell("\"That one? He'll be out before the night's over. Straight bourbon, no ice, and beer chasers. I'm surprised he can stand up now. He's had three already.\"\n");
      return true;
    } else if (g.PRSI == GLOBAL_OSTMANN) {
      if (hasFlag(g.PRSO, TOLD)) {
        tell("\"He's taking ", D(VERONICA), "'s death hard. I wonder why.\"\n");
        return true;
      } else {
        tell("\"He's very pleased with himself, isn't he?\"\n");
        return true;
      }
    } else if (g.PRSI == GLOBAL_BUTLER) {
      tell("\"He's been quite helpful. He obviously knows his job.\"\n");
      return true;
    } else {
      return await I_WOULDNT_KNOW();
    }
  } else {
    return false;
  }
}

async function I_WOULDNT_KNOW() {
  tell("\"I wouldn't know.\"\n");
  return true;
}

async function DRINK_F() {
  let ow = 0;
  ow = g.WINNER;
  if (isVerb(V.ASK_FOR)) {
    if (g.HERE == BALLROOM_9) {
      g.WINNER = BARTENDER;
      await PERFORM(V.GIVE, DRINK, ow);
      g.WINNER = ow;
      return true;
    } else {
      tell("Drinks may be obtained at the bar.\n");
      return true;
    }
  } else if (isVerb(V.THROW, V.POUR_ON)) {
    putProp(g.PRSO, P.SIZE, 5);
    return false;
  } else if (isVerb(V.DRINK)) {
    if (!(g.PRSO == DRINK)) {
      tell("Perhaps you've had one too many already. There is no drink");
      return await TELL_HERE();
    } else if (eq(getProp(DRINK, P.SIZE), 5)) {
      tell("It's empty. If you want more, you'll need a refill.\n");
      return true;
    } else {
      putProp(DRINK, P.SIZE, getProp(DRINK, P.SIZE) - 1);
      tell("You sip the drink. It's cold and tasty, but perhaps a little stronger than you would like.\n");
      return true;
    }
  } else if (isVerb(V.TAKE)) {
    if (loc(DRINK) == PLAYER) {
      tell("You already have one.\n");
      return true;
    } else if ((g.HERE == BALLROOM_9) && !(loc(DRINK) == g.HERE)) {
      await PERFORM(V.ORDER, DRINK);
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function G_BARTENDER(garg) {
  if (!garg) {
    return await IMOVEMENT(BARTENDER, G_BARTENDER.id);
  } else {
    return false;
  }
}

async function DETECTIVE_DESC_F(rarg = false) {
  await THE_PRINT(DETECTIVE, true);
  if (eq(loc(DETECTIVE), BALLROOM_8, BALLROOM_9)) {
    tell(" stands nearby, weighing evidence.\n");
    return true;
  } else if (loc(DETECTIVE) == OFFICE) {
    g.LAST_FROB = g.FROB;
    g.FROB = await PICK_ONE(g.OFFICE_FROBS);
    tell(" is examining ");
    await THE_PRINT(g.FROB);
    tell(".\n");
    return true;
  } else {
    tell(" is here");
    if (eq(await META_LOC(CORPSE), g.HERE)) {
      tell(", examining ");
      await DPRINT(CORPSE);
    } else if ((g.DETECTIVE_SEEN < 5) && (g.DETECTIVE_SEEN_CORPSE$ || g.DETECTIVE_SEEN_ROPE$ || g.DETECTIVE_SEEN_BULLET$)) {
      tell(", eyeing you suspiciously");
    }
    tell(".\n");
    return true;
  }
}

async function DETECTIVE_F() {
  let oseen = 0;
  if (g.WINNER == DETECTIVE) {
    if (isVerb(V.GIVE) && (g.PRSO == DETECTIVE_COAT) && (g.PRSI == BUTLER)) {
      if (loc(BUTLER) == g.HERE) {
        await THE_PRINT(DETECTIVE, true);
        tell(" politely refuses to yield the trenchcoat.\n");
      }
      return true;
    } else if (!g.DETECTIVE_BEEN_TO_OFFICE$ && (loc(DETECTIVE) == g.HERE) && !(isVerb(V.$DISCOVER, V.$REVEAL))) {
      tell("\"Can't this wait until I've visited the scene of the crime?\"\n");
      return true;
    } else if (isVerb(V.LOOK_INSIDE) && (g.PRSO == FAIRY_MASK)) {
      if (loc(HAIR) == FAIRY_MASK) {
        clearFlag(HAIR, INVISIBLE);
        g.WINNER = PLAYER;
        await PERFORM(V.SHOW, HAIR, DETECTIVE);
        g.WINNER = DETECTIVE;
        return true;
      } else {
        tell("\"Yes, I'm looking... What's inside that's so interesting? I don't see any blood or anything.\"\n");
        return true;
      }
    } else if (isVerb(V.ARREST, V.ACCUSE)) {
      if (g.PRSI == GLOBAL_EMBEZZLEMENT) {
        tell("\"We'll worry about that after we've solved the murder, okay?\"\n");
        return true;
      } else if (g.PRSO == OBJECT_PAIR) {
        if (get(g.P_PRSO, g.P_MATCHLEN) > 2) {
          tell("\"Sure, why don't I just run them all in?\"\n");
          return true;
        } else if (getProp(get(g.P_PRSO, 1), P.CHARACTER) && getProp(get(g.P_PRSO, 2), P.CHARACTER)) {
          return await ARREST(await LOCALIZE(get(g.P_PRSO, 1)), await LOCALIZE(get(g.P_PRSO, 2)));
        } else {
          tell("\"Arrested development, that's what you've got.\"\n");
          return true;
        }
      } else if (getProp(g.PRSO, P.CHARACTER) && !(g.PRSO == VERONICA || g.PRSO == GLOBAL_VERONICA)) {
        if (g.DETECTIVE_SEEN > 4) {
          return await ARREST(await LOCALIZE(g.PRSO));
        } else {
          tell("\"Whoa! Who's ");
          await THE_PRINT(DETECTIVE);
          tell(" here? If you can give me enough good reasons to arrest someone, I might listen to you, but you haven't given me enough!\"\n");
          return true;
        }
      } else {
        tell("\"That's the silliest thing I've ever heard.\"\n");
        return true;
      }
    } else if (isVerb(V.ANALYZE)) {
      if (!(eq(await META_LOC(g.PRSO), g.HERE, POLICE_LAB))) {
        await NOT_HERE(g.PRSO);
        return true;
      } else if (g.PRSO == GLASS) {
        return await CHECK_GLASS();
      } else if (g.PRSI == GLOBAL_FINGERPRINTS) {
        tell("\"I doubt we'll find any ", D(GLOBAL_FINGERPRINTS), " on ");
        await THE_PRINT(g.PRSO);
        tell(".\"\n");
        return true;
      } else if (g.PRSO == STAIN) {
        await THE_PRINT(DETECTIVE, true);
        tell(" reaches down and snips a small sample of stained cloth from the costume.\n");
        return await CHECK_JUNK(STAIN_SAMPLE);
      } else if (g.PRSO == HAIR) {
        if (loc(HAIR) == FAIRY_MASK) {
          if (!g.DETECTIVE_SEEN_HAIR$) {
            g.DETECTIVE_SEEN_HAIR$ = true;
            g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
          }
          return await CHECK_JUNK(HAIR);
        } else {
          tell("\"What's the point of analyzing this hair after you've been fooling around with it?\"\n");
          return true;
        }
      } else if (g.PRSO == FAIRY_MASK) {
        return await CHECK_JUNK(FAIRY_MASK);
      } else if (g.PRSO == CORPSE) {
        tell("\"I think I'll leave that to the coroner. For the moment, it's enough that she's dead.\"\n");
        return true;
      } else {
        tell("\"I don't think an analysis of ");
        await THE_PRINT(g.PRSO);
        tell(" would reveal any useful information.\"\n");
        return true;
      }
    } else if (isVerb(V.COMPARE)) {
      if (((g.PRSO == HAIR || g.PRSO == VERONICA_HAIR) || (g.PRSO == ALICIA_HAIR || g.PRSO == LINDA_HAIR)) && ((g.PRSI == HAIR || g.PRSI == VERONICA_HAIR) || (g.PRSI == ALICIA_HAIR || g.PRSI == LINDA_HAIR))) {
        tell("The detective compares the hairs. \"These hairs are ");
        if ((g.PRSO == g.PRSI || g.PRSO == HAIR) && (g.PRSI == g.PRSO || g.PRSI == ALICIA_HAIR)) {
          tell("quite similar");
        } else {
          tell("not alike");
        }
        tell(".\"\n");
        return true;
      } else {
        tell("\"How about apples and oranges?\"\n");
        return true;
      }
    } else if (isVerb(V.TELL, V.ASK_ABOUT)) {
      tell("\"I'll ask the questions here.\"\n");
      return true;
    } else if (isVerb(V.FIND)) {
      if (eq(await META_LOC(g.PRSO), g.HERE)) {
        tell("\"Not too observant, are you?\"\n");
        return true;
      } else {
        tell("\"It would help if you told me where to look.\"\n");
        return true;
      }
    } else if ((await DONT_HANDLE$()) || isVerb(V.FINGERPRINT)) {
      return false;
    } else {
      tell("\"I'm very busy. There's been a murder, in case you haven't noticed.\"\n");
      return true;
    }
  } else if (isVerb(V.PHONE)) {
    await PERFORM(V.PHONE, POLICE);
    return true;
  } else if (isVerb(V.EXAMINE) && (g.PRSO == DETECTIVE)) {
    await THE_PRINT(DETECTIVE, true);
    tell(" is quiet and intense, wearing a trenchcoat and a crumpled hat. The trenchcoat and hat are still wet from the rain.\n");
    return true;
  } else if (isVerb(V.SHOW, V.GIVE) && (g.PRSI == DETECTIVE)) {
    oseen = g.DETECTIVE_SEEN;
    await THE_PRINT(DETECTIVE, true);
    if (g.PRSO == CORPSE) {
      tell(" comes over.");
    } else if (!g.DETECTIVE_BEEN_TO_OFFICE$) {
      tell(" says, \"Can't this wait until I've visited the scene of the crime?\"\n");
      return true;
    } else if (loc(g.PRSO) == DETECTIVE) {
      tell(" looks at you strangely and then shows ");
      await THE_PRINT(g.PRSO);
      tell(" to you.\n");
      return true;
    } else if ((g.PRSO == GLASS_ANALYSIS || g.PRSO == HAIR_ANALYSIS) || (g.PRSO == NULL_ANALYSIS || g.PRSO == STAIN_ANALYSIS)) {
      move(g.PRSO, DETECTIVE);
      tell(" takes it back. \"Thanks, I hope you found it interesting.\"\n");
      return true;
    } else if ((g.PRSO == HAIR) && (loc(HAIR) == FAIRY_MASK)) {
      if (loc(FAIRY_MASK) == DETECTIVE) {
        tell(" looks inside the mask.");
      } else {
        setFlag(FAIRY_MASK, TRYTAKEBIT);
        move(FAIRY_MASK, DETECTIVE);
        tell(" takes the mask, noting the hair as you point it out.");
      }
    } else if (loc(g.PRSO) == FIREPLACE) {
      move(g.PRSO, DETECTIVE);
      tell(" snatches it from the fireplace.");
    } else if (loc(g.PRSO) == GLOBAL_OBJECTS) {
      tell(" is confused. \"What are you trying to tell me about?\"\n");
      return true;
    } else if (hasFlag(g.PRSO, PERSON) || (await GLOBAL_IN$(g.PRSO, g.HERE)) || !(hasFlag(g.PRSO, TAKEBIT))) {
      tell(" looks at ");
      await THE_PRINT(g.PRSO);
      tell(".");
    } else if (hasFlag(g.PRSO, TRYTAKEBIT) && !(g.PRSO == GLASS || g.PRSO == BULLET || g.PRSO == FAIRY_MASK) && !(await HELD$(g.PRSO, PLAYER))) {
      tell(" says, \"Would you mind bringing it over?\"\n");
      return true;
    } else if (isVerb(V.SHOW)) {
      move(g.PRSO, DETECTIVE);
      setFlag(g.PRSO, TRYTAKEBIT);
      tell(" looks at ");
      await THE_PRINT(g.PRSO);
      tell(" for a moment, then takes it.");
    } else {
      move(g.PRSO, DETECTIVE);
      setFlag(g.PRSO, TRYTAKEBIT);
      tell(" takes ");
      await THE_PRINT(g.PRSO);
      tell(".");
    }
    if (g.JUNK_COUNT == 4) {
      tell(" \"Go away and stop bothering me!\"\n");
    } else if (g.PRSO == CORPSE) {
      tell(" ");
      await THE_PRINT(DETECTIVE, true);
      if (g.DETECTIVE_SEEN_CORPSE$) {
        tell(" looks at the corpse, and replies, \"Show me something I haven't already seen!\"\n");
      } else {
        g.DETECTIVE_SEEN_CORPSE$ = true;
        g.DETECTIVE_SEEN = g.DETECTIVE_SEEN;
        tell(" examines the body.\n");
      }
    } else if (g.PRSO == ROPE) {
      tell(" ");
      await THE_PRINT(DETECTIVE, true);
      tell(" examines the rope");
      if (!g.DETECTIVE_SEEN_ROPE$) {
        g.DETECTIVE_SEEN_ROPE$ = true;
        g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
        tell(" with interest");
      }
      tell(".\n");
    } else if (g.PRSO == CARD) {
      if (g.DETECTIVE_SEEN_CARD$) {
        tell(" \"I've seen that already.\"\n");
      } else {
        g.DETECTIVE_SEEN_CARD$ = true;
        g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
        if (g.DETECTIVE_SEEN_AGREEMENT$) {
          tell(" \"This certainly seems to implicate ", D(COCHRANE), ". He seems hot-headed enough to commit murder, and the sale provides a motive.\"\n");
        } else {
          tell(" \"I wonder what this means? What was she doing that she might regret? It certainly casts some suspicion on ", D(COCHRANE), ".\"\n");
        }
      }
    } else if ((g.PRSO == SALE_AGREEMENT) || ((g.PRSO == SALE_FOLDER) && (loc(SALE_AGREEMENT) == SALE_FOLDER))) {
      if (!g.DETECTIVE_SEEN_AGREEMENT$) {
        g.DETECTIVE_SEEN_AGREEMENT$ = true;
        g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
        tell(" \"If someone wanted to prevent this sale, it might have been worth committing a murder to do. ");
        if (g.DETECTIVE_SEEN_CARD$) {
          tell("Could it have been ", D(COCHRANE));
        } else {
          tell("But who could that have been");
        }
        tell("?\"\n");
      } else {
        tell(" \"Yes, I've seen that. Stop bothering me!\"\n");
      }
    } else if (g.PRSO == ALICIA_COAT) {
      if (!g.DETECTIVE_SEEN_COAT$) {
        g.DETECTIVE_SEEN_COAT$ = true;
        if (!g.DETECTIVE_TOLD_ABOUT_RAIN$) {
          tell(" \"I don't see the significance of this. It's been raining all night, as far as I know. Everyone's coat is wet.\"\n");
        } else {
          g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 2;
          tell(" \"Hmm. When Alicia arrived it wasn't raining, and this coat is wet! She must have really been outside during the rain.\"\n");
        }
      } else {
        tell(" \"Yes, it's still wet.\"\n");
      }
    } else if ((g.PRSO == TRUST_DOCUMENTS) || ((g.PRSO == TRUST_FOLDER) && (loc(TRUST_DOCUMENTS) == TRUST_FOLDER))) {
      if (!g.DETECTIVE_SEEN_TRUST_DOCUMENTS$) {
        g.DETECTIVE_SEEN_TRUST_DOCUMENTS$ = true;
        g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
        clearFlag(TRUST_DOCUMENTS, NDESCBIT);
        tell(" \"Where did you get this? It's important!");
        if (g.DETECTIVE_SEEN_LIST$) {
          tell(" This means that ", D(MICHAEL), " and ", D(COL_MARSTON), " were embezzling from the family trust. And further, ", D(VERONICA), " knew it!");
        }
        tell("\"\n");
      } else {
        tell(" \"Don't you have anything new to show me?\"\n");
      }
    } else if (g.PRSO == GLASS) {
      if (!g.DETECTIVE_SEEN_GLASS$) {
        tell(" ");
        await CHECK_GLASS();
      } else {
        tell(" \"It's the same glass, right?\"\n");
      }
    } else if (g.PRSO == FAIRY_MASK) {
      tell(" \"What's so interesting about this mask?\"\n");
    } else if (g.PRSO == HAIR) {
      if ((loc(HAIR) == FAIRY_MASK) && !(hasFlag(HAIR, INVISIBLE))) {
        if (!g.DETECTIVE_SEEN_HAIR$) {
          g.DETECTIVE_SEEN_HAIR$ = true;
          g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
          tell(" \"A ", D(HAIR), ", eh? ", D(VERONICA), "'s hair was blonde. How did a hair this color get into this mask?\"\n");
        } else {
          tell(" \"Same old hair, eh?\"\n");
        }
      } else {
        tell(" \"It looks like a hair. What is it supposed to prove? You're going to be in deep trouble if you've been disturbing evidence!\"\n");
      }
    } else if (g.PRSO == INVESTOR_LIST) {
      if (!g.DETECTIVE_SEEN_LIST$) {
        g.DETECTIVE_SEEN_LIST$ = true;
        g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
        if (g.DETECTIVE_SEEN_TRUST_DOCUMENTS$) {
          tell(" ");
          await THE_PRINT(DETECTIVE, true);
          tell(" reads the paper with growing excitement. \"This is it! The motive I've been looking for!\"\n");
        } else {
          tell(" \"What's the significance of this? ", D(COL_MARSTON), " and ", D(MICHAEL), " were co-investors in something?\"\n");
        }
      } else {
        tell(" \"Seen it before.\"\n");
      }
    } else {
      g.JUNK_COUNT = g.JUNK_COUNT + 1;
      tell(" ", S(get(g.JUNK_STRINGS, g.JUNK_COUNT)), "\n");
    }
    if (g.DETECTIVE_SEEN > oseen) {
      await GRAB_ATTENTION(DETECTIVE);
    }
    return true;
  } else if (isVerb(V.TELL_ME) && (g.PRSO == DETECTIVE)) {
    if (g.PRSI == WEATHER) {
      if (g.SAW_RAIN_SLACK_OFF$) {
        if (!g.DETECTIVE_TOLD_ABOUT_RAIN$) {
          g.DETECTIVE_TOLD_ABOUT_RAIN$ = true;
          if (!g.DETECTIVE_SEEN_COAT$) {
            tell("You try to explain the significance of the rain, but ");
            await THE_PRINT(DETECTIVE);
            tell(" doesn't understand what you're getting at.\n");
          } else {
            g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 2;
            await THE_PRINT(DETECTIVE, true);
            tell(" listens as you explain how when Alicia arrived the rain was falling very lightly, but that her overcoat was soaked, which is why you turned it over to the authorities. ");
            await THE_PRINT(DETECTIVE, true);
            tell(" says, \"That may mean she was here earlier when the rain was pelting down, that she didn't arrive when she said she did.\"\n");
          }
        } else {
          tell("\"You've already told me this.\"\n");
        }
      } else {
        tell("You haven't seen anything significant about the weather, so you can't tell ");
        await THE_PRINT(DETECTIVE);
        tell(" about it.\n");
      }
    } else if ((g.PRSI == BMW) && g.DETECTIVE_SEEN_TRUST_DOCUMENTS$) {
      tell("\"Ah! Either ", D(MICHAEL), " or someone with access to his keys must have put the documents there.\"\n");
    } else {
      await THE_PRINT(DETECTIVE, true);
      tell(" doesn't seem very interested.\n");
    }
    if (g.DETECTIVE_SEEN > oseen) {
      await GRAB_ATTENTION(DETECTIVE);
    }
    return true;
  } else if (isVerb(V.ASK_ABOUT) && (g.PRSO == DETECTIVE)) {
    if (g.PRSI == DETECTIVE) {
      tell("\"I'm a detective. That's all you need to know right now.\"\n");
      return true;
    } else if (g.PRSI == DUFFY || g.PRSI == GLOBAL_DUFFY) {
      tell("\"", D(DUFFY), " is my assistant, and a finer public servant you're unlikely to find.\"\n");
      return true;
    } else {
      tell("\"I don't reveal my methods, particularly to potential suspects.\"\n");
      return true;
    }
  } else if (isVerb(V.TAKE) && (loc(g.PRSO) == DETECTIVE)) {
    tell("\"You can't have that. It's evidence.\"\n");
    return true;
  } else if (isVerb(V.REPLY)) {
    await THE_PRINT(DETECTIVE, true);
    tell(" listens intently.\n");
    return true;
  } else if (await CAUGHT_WITH_BODY$()) {
    if (!g.DETECTIVE_SEEN_CORPSE$) {
      g.DETECTIVE_SEEN_CORPSE$ = true;
      g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
    }
    await I_START_ARREST();
    await THE_PRINT(DETECTIVE, true);
    tell(" sees you carrying the body.\n");
    return true;
  } else {
    return false;
  }
}

async function ITLL_WAIT() {
  tell("\"It will have to wait until ", D(DUFFY), " gets back from the lab.\"\n");
  return true;
}

async function CHECK_GLASS() {
  if (loc(DUFFY) == POLICE_LAB) {
    await ITLL_WAIT();
    return true;
  }
  if (!g.DETECTIVE_SEEN_GLASS$) {
    g.DETECTIVE_SEEN_GLASS$ = true;
    g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
  }
  if ((g.GLASS_ANALYZED$ && !g.PRSI) || (g.GLASS_ANALYZED_FOR_PRINTS$ && (g.PRSI == GLOBAL_FINGERPRINTS))) {
    tell("\"That's already been done.\"\n");
    return true;
  } else {
    if (!g.GLASS_ANALYZED$) {
      g.GLASS_ANALYZED$ = true;
      g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
    }
    await TELL_ANALYZE(GLASS);
    if (g.PRSI == GLOBAL_FINGERPRINTS) {
      if (!g.GLASS_ANALYZED_FOR_PRINTS$) {
        g.GLASS_ANALYZED_FOR_PRINTS$ = true;
        if (!(hasFlag(GLASS, TOUCHBIT))) {
          g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
        }
      }
      tell(" for ", D(GLOBAL_FINGERPRINTS));
    }
    return await DUFFY_TO_LAB(GLASS);
  }
}

async function CHECK_JUNK(obj) {
  if (loc(DUFFY) == POLICE_LAB) {
    await ITLL_WAIT();
    return true;
  }
  await TELL_ANALYZE(obj);
  return await DUFFY_TO_LAB(obj);
}

async function TELL_ANALYZE(obj) {
  tell("\"", D(DUFFY), ", analyze ");
  await THE_PRINT(obj);
  return true;
}

async function DUFFY_TO_LAB(obj) {
  let gt = 0;
  tell("!\" ", D(DUFFY), " ");
  if (!(loc(DUFFY) == g.HERE)) {
    tell("appears as if out of nowhere and ");
  }
  tell("takes ");
  await THE_PRINT(obj);
  tell(". He seems to almost disappear. \"He's a fine public servant,\" comments ");
  await THE_PRINT(DETECTIVE);
  tell(".\n");
  gt = get(g.GOAL_TABLES, DUFFY_C);
  put(gt, GOAL_ENABLE, false);
  put(gt, ATTENTION, 0);
  move(DUFFY, POLICE_LAB);
  enable(await QUEUE(I_DUFFY_RETURNS.id, 20));
  move(obj, POLICE_LAB);
  if (obj == GLASS) {
    obj = GLASS_ANALYSIS;
    if (g.GLASS_ANALYZED_FOR_PRINTS$) {
      if (hasFlag(GLASS, TOUCHBIT)) {
        putProp(GLASS_ANALYSIS, P.TEXT, g.GLASS_ANALYSIS_Q);
      } else {
        setFlag(GLASS_ANALYSIS, ALICIABIT);
        putProp(GLASS_ANALYSIS, P.TEXT, g.GLASS_ANALYSIS_P);
      }
    }
  } else if (obj == HAIR) {
    obj = HAIR_ANALYSIS;
  } else if (obj == MASK) {
    obj = MASK_ANALYSIS;
  } else if (obj == STAIN) {
    obj = STAIN_ANALYSIS;
  } else {
    obj = NULL_ANALYSIS;
  }
  return move(obj, DUFFY);
}

async function I_DUFFY_RETURNS() {
  let aobj = 0, gt = 0, priority = 0, final = 0;
  move(DUFFY, loc(DETECTIVE));
  await WHERE_UPDATE(DUFFY, g.HERE == loc(DETECTIVE));
  gt = get(g.GOAL_TABLES, DUFFY_C);
  final = get(gt, GOAL_F);
  if (priority = get(gt, GOAL_QUEUED)) {
    await ESTABLISH_GOAL(DUFFY, priority);
  }
  await ESTABLISH_GOAL(DUFFY, final, priority);
  put(gt, GOAL_ENABLE, true);
  if (aobj = first(DUFFY)) {
    if (loc(DETECTIVE) == g.HERE) {
      move(aobj, PLAYER);
      tell(D(DUFFY), " returns with the analysis. ");
      await THE_PRINT(DETECTIVE, true);
      tell(" reads it, then hands it to you. It reads, omitting the irrelevant details:\n");
      tell("\n", S(getProp(aobj, P.TEXT)), "\n");
      return true;
    } else {
      setFlag(aobj, TOLD);
      move(aobj, DETECTIVE);
      return false;
    }
  } else {
    return false;
  }
}

async function TELL_RINGS() {
  await THE_PRINT(DETECTIVE, true);
  tell(" rings the doorbell, then stands and waits.\n");
  return true;
}

async function G_DETECTIVE(garg) {
  let l = loc(DETECTIVE), flg = false;
  if (!garg) {
    return await IMOVEMENT(DETECTIVE, G_DETECTIVE.id);
  } else if (garg == G_IMPATIENT) {
    await THE_PRINT(DETECTIVE, true);
    tell(" says, \"If you'll excuse me, I have an investigation to conduct.\"\n");
    return true;
  } else if (garg == G_REACHED || garg == G_ALREADY) {
    if ((g.TARGET == PLAYER) && (flg = await PLAYER_ARRESTED$(DETECTIVE, garg))) {
      return true;
    }
    if ((loc(DETECTIVE) == g.HERE) && (await LAB_RESULTS_TO_PLAYER(garg))) {
      garg = G_ALREADY;
    }
    if (loc(DETECTIVE) == PORCH) {
      g.NEW_ARRIVAL = DETECTIVE;
      await ESTABLISH_GOAL(BUTLER, HALL, true);
      if (g.HERE == PORCH) {
        if (!g.PLAYER_HIDING) {
          await THE_PRINT(DETECTIVE, true);
          tell(" looks you over suspiciously. No one said that a costume party was in progress. ");
        }
        await TELL_RINGS();
      } else if (g.HERE == CIRCLE) {
        await TELL_RINGS();
      } else if (!(await OUTSIDE$(g.HERE))) {
        await THE_PRINT(DOORBELL, true);
        tell(" has just rung.\n");
      }
    } else if (loc(DETECTIVE) == OFFICE) {
      g.DETECTIVE_BEEN_TO_OFFICE$ = true;
    }
    if (await DETECTIVE_FINDS_BODY$(garg)) {
      flg = true;
    } else if (await GO_AFTER_BODY$(DETECTIVE)) {
      if (loc(DETECTIVE) == g.HERE) {
        await THE_PRINT(DETECTIVE, true);
        tell(" makes a quick examination of the vicinity.\n");
      }
    } else if ((garg == G_REACHED) && (loc(DETECTIVE) == g.HERE)) {
      await THE_PRINT(DETECTIVE, true);
      tell(" stops, looks carefully around, and then begins a detailed examination of the vicinity.\n");
    }
    if (await DETECTIVE_SEES_ROPE$(l)) {
      if (l == g.HERE) {
        await THE_PRINT(DETECTIVE, true);
        tell(" looks significantly at the rope. You catch a very suspicious sidelong glance at your costume. You can almost hear the click of the lock on a jail cell.\n");
        flg = true;
      }
    }
    if (loc(DETECTIVE) == BALLROOM_8) {
      await I_START_ARREST();
    }
    return flg;
  } else if (garg == G_ENROUTE) {
    if (g.TARGET == PLAYER) {
      return await PLAYER_ARRESTED$(DETECTIVE, garg);
    } else if (await DETECTIVE_FINDS_BODY$(garg)) {
      return true;
    } else if (loc(DETECTIVE) == g.HERE) {
      return await LAB_RESULTS_TO_PLAYER();
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function DETECTIVE_SEES_ROPE$(l) {
  if (eq(await META_LOC(ROPE), l) && !g.DETECTIVE_SEEN_ROPE$) {
    g.DETECTIVE_SEEN_ROPE$ = true;
    return g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
  } else {
    return false;
  }
}

async function DETECTIVE_FINDS_BODY$(garg) {
  let l = loc(DETECTIVE), lc = loc(CORPSE), bullet$ = false;
  if (lc && eq(await META_LOC(CORPSE), l) && !g.DETECTIVE_SEEN_CORPSE$) {
    setFlag(DETECTIVE, TOLD);
    g.DETECTIVE_SEEN_CORPSE$ = true;
    g.DETECTIVE_SEEN = g.DETECTIVE_SEEN + 1;
    await OPEN_HIDING_PLACE();
    await UNPRIORITIZE(DETECTIVE);
    await GOALS$(DETECTIVE, false);
    enable(await QUEUE(I_AMBULANCE.id, 20));
    if ((loc(DETECTIVE) == OFFICE) && eq(loc(BULLET), CORPSE, OFFICE)) {
      bullet$ = true;
      clearFlag(BULLET, INVISIBLE);
      move(BULLET, DETECTIVE);
      g.DETECTIVE_SEEN_BULLET$ = true;
      if (hasFlag(BULLET, RMUNGBIT)) {
        g.DETECTIVE_SEEN_BULLET_PRINTS$ = true;
      }
    }
    if (!(loc(DUFFY) == l) && !(loc(DUFFY) == POLICE_LAB)) {
      await ESTABLISH_GOAL(DUFFY, l, true);
    }
    if (l == g.HERE) {
      await THE_PRINT(DETECTIVE, true);
      tell(" ");
      if (garg == G_REACHED) {
        tell("arrives and ");
      }
      if ((loc(CORPSE) == PLAYER) || (loc(lc) == PLAYER)) {
        g.TARGET = PLAYER;
        tell("stops short, seeing you carrying the body.\n");
        await DETECTIVE_SEES_ROPE$(l);
        return await PLAYER_ARRESTED$(DETECTIVE);
      } else if (!(loc(lc) == ROOMS)) {
        if (loc(DUFFY) == l) {
          tell("with a nod to ", D(DUFFY), ", takes over.");
        } else {
          await TELL_COMES_UPON(lc);
          if (!(lc == CHAIR)) {
            tell("With an air of anticipation, ");
            await THE_PRINT(DETECTIVE);
            tell(" looks inside. ");
          }
          await TELL_BODY_THERE();
        }
      } else {
        tell("immediately notices the body.");
      }
      if (bullet$) {
        tell(" Seeing a glint of silver, the detective stoops down and carefully retrieves ");
        await PRINTA(BULLET);
        tell(".");
      }
      if (!(l == OFFICE) && !(loc(DUFFY) == l)) {
        tell(" \"", D(DUFFY), ", come here, I want you!\"");
      }
      tell(" As first priority, ");
      await THE_PRINT(DETECTIVE);
      tell(" checks out the corpse. While you watch, it is efficiently examined, touched, looked at, looked under, fingerprinted, and so on.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function OPEN_HIDING_PLACE() {
  let l = loc(CORPSE);
  if ((l == HAMPER || l == WINDOW_SEAT || l == MERCEDES_TRUNK) || (l == BMW_TRUNK)) {
    setFlag(l, OPENBIT);
    if (loc(PLAYER) == l) {
      return move(PLAYER, g.HERE);
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function I_START_ARREST() {
  if ((g.DETECTIVE_SEEN > 4) && !g.PLAYER_SEEN_WITH_BODY$) {
    return false;
  } else if ((g.DETECTIVE_SEEN_CORPSE$ || g.DUFFY_SEEN_CORPSE$) && !(loc(DUFFY) == POLICE_LAB)) {
    g.TARGET = PLAYER;
    await STALK_PLAYER(DETECTIVE);
    await STALK_PLAYER(DUFFY);
  } else {
    enable(await QUEUE(I_START_ARREST.id, 10));
  }
  return false;
}

async function STALK_PLAYER(who) {
  if (await DIR_FROM(g.HERE, loc(who))) {
    move(who, g.HERE);
    return await PLAYER_ARRESTED$(who, G_REACHED);
  } else {
    return await ESTABLISH_GOAL(who, g.HERE);
  }
}

async function LAB_RESULTS_TO_PLAYER(garg = G_ALREADY) {
  let f = 0, n_ = 0, first_ = true;
  f = first(DETECTIVE);
  for (;;) {
    if (!f) {
      return !first_;
    }
    n_ = next(f);
    if (hasFlag(f, TOLD)) {
      clearFlag(f, TOLD);
      move(f, PLAYER);
      if (first_) {
        first_ = false;
        await THE_PRINT(DETECTIVE, true);
        if (garg == G_REACHED) {
          tell(" comes up to you and");
        }
        tell(" interrupts.");
      }
      tell("\n\"");
      if (f == NULL_ANALYSIS) {
        tell("analysis");
      } else {
        await THE_PRINT(f, true);
      }
      tell(" is back from the lab. I thought you might be interested in what it says.\" ");
      await THE_PRINT(DETECTIVE, true);
      tell(" hands it to you. It reads, omitting the irrelevant details:\n\n", S(getProp(f, P.TEXT)), "\n");
    }
    f = n_;
  }
}

async function TELL_ON_SCENE(who) {
  await DPRINT(who, true);
  tell(" arrives on the scene");
  return true;
}

async function PLAYER_ARRESTED$(who, garg = G_ALREADY) {
  if ((g.DETECTIVE_SEEN > 4) && !g.PLAYER_SEEN_WITH_BODY$) {
    g.TARGET = false;
    return false;
  } else if ((who == DETECTIVE) && (loc(DETECTIVE) == g.HERE)) {
    if (g.DUFFY_SNARFED) {
      await TELL_ON_SCENE(DETECTIVE);
      tell(", surveys the situation, and says \"Good work, Sergeant!\" ");
      await THE_PRINT(DETECTIVE, true);
      tell(" eyes you with satisfaction. \"You're under arrest for the murder of ", D(VERONICA), " Ashcroft.\" The standard warnings are given. ", D(DUFFY));
    } else {
      setFlag(PLAYER, TOLD);
      await THE_PRINT(DETECTIVE, true);
      if (!(garg == G_ALREADY)) {
        tell(" sees you, approaches warily, and");
      }
      tell(" grabs you firmly by the wrist, and with a practiced twist, slips the cuffs on you. \"You're under arrest for the murder of ", D(VERONICA), " Ashcroft.\" The standard warnings are given. ", D(DUFFY), " appears, as though out of nowhere, and");
    }
    tell(" escorts you out to the waiting police car. All your protests are ignored.\n\nIn the subsequent trial, you are ");
    if (g.PLAYER_FOLLOWED_VERONICA$ || g.PLAYER_BEEN_TO_OFFICE$) {
      tell("convicted of second degree murder. There was damning evidence, such as");
    } else {
      tell("acquitted, in spite of");
    }
    tell(" the fact that");
    if (g.DETECTIVE_BEEN_TO_OFFICE$ && !g.DETECTIVE_SEEN_ROPE$) {
      tell(" you attempted to hide the lariat which");
    } else {
      tell(" your lariat");
    }
    tell(" was the murder weapon");
    if (g.DETECTIVE_SEEN_BULLET$) {
      tell(" and the bullet from your gunbelt");
      if (g.DETECTIVE_SEEN_BULLET_PRINTS$) {
        tell(" (with both your ", D(GLOBAL_FINGERPRINTS), " and ", D(VERONICA), "'s on it)");
      }
      tell(" was found near the body");
    }
    tell(".");
    if (g.PLAYER_FOLLOWED_VERONICA$) {
      tell(" Also, you were presumably the last person to see her alive, since you charged off after her when she spilled her drink.");
    }
    if (g.PLAYER_SEEN_WITH_BODY$) {
      tell(" Of course, you were seen moving the body around after the murder.");
    } else if (g.PLAYER_MOVED_BODY$) {
      tell(" Stupidly, you moved the body after the murder.");
    }
    tell(" Finally, several guests testified against you as a nosy and suspicious character.\n");
    tell("\nHowever, ");
    await THE_PRINT(DETECTIVE);
    tell(" and ", D(DUFFY), ", nagged by doubt, continue the investigation on their own time. Their brilliant detective work unravels the tangled mess behind the murder. You are released, and as you leave jail, you can't help but think that if you had been able to figure out what was going on that night, you might have won yourself a Pulitzer Prize by now.\n");
    return await FINISH();
  } else if ((who == DUFFY) && (loc(DUFFY) == g.HERE)) {
    if (!g.DUFFY_SNARFED) {
      setFlag(PLAYER, TOLD);
      g.DUFFY_SNARFED = true;
      put(get(g.GOAL_TABLES, PLAYER_C), GOAL_S, false);
      put(get(g.GOAL_TABLES, DUFFY_C), GOAL_ENABLE, false);
      await ESTABLISH_GOAL(DETECTIVE, g.HERE);
      tell(D(DUFFY));
      if (g.PLAYER_HIDING) {
        tell(" immediately penetrates the concealment of ");
        await THE_PRINT(g.PLAYER_HIDING);
        tell(". He");
        g.PLAYER_HIDING = false;
      }
      if (!(eq(loc(PLAYER), g.HERE))) {
        move(PLAYER, g.HERE);
      }
      tell(" grabs you with a grip of iron. \"");
      await THE_PRINT(DETECTIVE, true);
      tell(" would like a word with you,\" he says.\n");
      return true;
    } else if (!(isVerb(V.TELL)) || g.PRSI) {
      tell(D(DUFFY), " maintains his iron grip as you wait apprehensively for the arrival of ");
      await THE_PRINT(DETECTIVE);
      tell(".\n");
      return true;
    } else {
      return false;
    }
  } else {
    await I_START_ARREST();
    return false;
  }
}

async function DUFFY_DESC_F(rarg = false) {
  tell(D(DUFFY));
  if (g.DUFFY_SNARFED) {
    tell(" is here, his iron grip immobilizing you.\n");
    return true;
  } else if ((loc(DUFFY) == OFFICE) && g.LAST_FROB) {
    tell(" is carefully checking over ");
    await THE_PRINT(g.LAST_FROB);
    tell(", making sure his boss has missed nothing.\n");
    return true;
  } else {
    tell(" waits nearby, ready to spring into action to serve his superior officer.\n");
    return true;
  }
}

async function DUFFY_F() {
  if (g.WINNER == DUFFY) {
    if (isVerb(V.GIVE) && (g.PRSO == DUFFY_COAT) && (g.PRSI == BUTLER)) {
      if (loc(BUTLER) == g.HERE) {
        tell(D(DUFFY), ", following the example of his boss, refuses to give up his raincoat.\n");
      }
      return true;
    } else if (isVerb(V.ANALYZE)) {
      tell("\"I perform analyses for ");
      await THE_PRINT(DETECTIVE);
      tell(". If you want something analyzed, that's how to do it.\"\n");
      return true;
    } else if (await DONT_HANDLE$()) {
      return false;
    } else {
      tell(D(DUFFY), " stands silently, intent upon his business, and ignores your request. You realize that his devotion to duty is so strong that he would be hard to distract.\n");
      return true;
    }
  } else if (isVerb(V.PHONE)) {
    await PERFORM(V.PHONE, POLICE);
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell(D(DUFFY), " is of medium height, very non-descript, very attentive to his boss, ");
    await THE_PRINT(DETECTIVE);
    tell(". He is in uniform.\n");
    return true;
  } else if (isVerb(V.ASK_ABOUT) && (g.PRSO == DUFFY)) {
    tell("\"You'd have to ask ");
    await THE_PRINT(DETECTIVE);
    tell(". His opinions are mine.\"\n");
    return true;
  } else if (isVerb(V.SHOW)) {
    if ((g.PRSO == CORPSE) && (g.PRSI == DUFFY)) {
      tell(D(DUFFY), " approaches.\n");
      return true;
    } else {
      tell("\"Perhaps that would interest the detective.\"\n");
      return true;
    }
  } else if (await CAUGHT_WITH_BODY$()) {
    g.DUFFY_SEEN_CORPSE$ = true;
    await I_START_ARREST();
    tell(D(DUFFY), " sees you carrying the body.\n");
    return true;
  } else {
    return false;
  }
}

async function CAUGHT_WITH_BODY$() {
  return isVerb(V.$DISCOVER) && (g.PRSO == CORPSE) && (loc(CORPSE) == PLAYER);
}

async function G_DUFFY(garg) {
  let flg = false;
  if (!garg) {
    return await IMOVEMENT(DUFFY, G_DUFFY.id);
  } else if ((garg == G_IMPATIENT) && !g.DUFFY_SNARFED) {
    tell(D(DUFFY), " says, \"I have work to do. Goodbye.\"\n");
    return true;
  } else if (garg == G_REACHED || garg == G_ALREADY) {
    if ((garg == G_REACHED) && (loc(DUFFY) == g.HERE)) {
      await TELL_ON_SCENE(DUFFY);
      tell(".\n");
      flg = true;
    }
    if (await DUFFY_FINDS_BODY$(garg)) {
      return true;
    } else {
      return flg;
    }
  } else if (garg == G_ENROUTE) {
    return await DUFFY_FINDS_BODY$(garg);
  } else {
    return false;
  }
}

async function TELL_COMES_UPON(lc) {
  tell("begins to search the room, and comes upon ");
  await THE_PRINT(lc);
  tell(". ");
  return true;
}

async function TELL_BODY_THERE() {
  tell(D(VERONICA), "'s body is there.");
  return true;
}

async function DUFFY_FINDS_BODY$(garg) {
  let l = loc(DUFFY), lc = loc(CORPSE);
  let $1;
  if (g.TARGET == PLAYER) {
    return await PLAYER_ARRESTED$(DUFFY, garg);
  } else if (lc && eq(await META_LOC(CORPSE), l) && !g.DUFFY_SEEN_CORPSE$) {
    setFlag(DUFFY, TOLD);
    await OPEN_HIDING_PLACE();
    g.DUFFY_SEEN_CORPSE$ = true;
    await UNPRIORITIZE(DUFFY);
    await GOALS$(DUFFY, false);
    if (!(loc(DETECTIVE) == l)) {
      await ESTABLISH_GOAL(DETECTIVE, l, true);
    }
    if (l == g.HERE) {
      if ((loc(CORPSE) == PLAYER) || (loc(lc) == PLAYER)) {
        await I_START_ARREST();
        tell(D(DUFFY), "'s eyes widen as he sees you brazenly carrying the corpse.\n");
        await PLAYER_ARRESTED$(DUFFY);
        return true;
      } else if (!(loc(lc) == ROOMS)) {
        if (loc(DETECTIVE) == l) {
          tell("He begins to lend his assistance.\n");
        } else {
          tell(D(DUFFY), " ");
          await TELL_COMES_UPON(lc);
          if (!(lc == CHAIR)) {
            tell("He looks at it suspiciously for a moment, then looks inside. ");
          }
          tell("His eyes widen. ");
          await TELL_BODY_THERE();
          crlf();
        }
      } else {
        if (garg == G_REACHED) {
          tell("He immediately");
        } else {
          tell(D(DUFFY), " suddenly");
          $1 = true;
          if ($1) {
          }
        }
        tell(" notices the body.\n");
      }
      if (!(l == OFFICE) && !(loc(DETECTIVE) == l)) {
        tell("He blows a small police whistle several times. \"", D(VERONICA), "'s body is here!\" he yells.\n");
      }
      tell(D(DUFFY));
      if (!g.DETECTIVE_SEEN_CORPSE$) {
        tell(" makes a preliminary examination of the corpse while he waits for ");
        await THE_PRINT(DETECTIVE);
        tell(".\n");
        return true;
      } else if (loc(DETECTIVE) == l) {
        tell(" examines the body, making a few comments to ");
        await THE_PRINT(DETECTIVE);
        tell(", who makes a few notes.\n");
        return true;
      } else {
        tell(" makes a few observations which he records in his notebook.\n");
        return true;
      }
    } else {
      return false;
    }
  } else if (lc) {
    await GO_AFTER_BODY$(DUFFY);
    return false;
  } else {
    return false;
  }
}

async function GO_AFTER_BODY$(who) {
  if (!g.DETECTIVE_BEEN_TO_OFFICE$ || g.DETECTIVE_SEEN_CORPSE$ || g.DUFFY_SEEN_CORPSE$ || (await LISTENING$(who))) {
    return false;
  } else if (hasFlag(CORPSE, RMUNGBIT) || g.PLAYER_SEEN_WITH_BODY$ || (await PROB(25))) {
    setFlag(CORPSE, RMUNGBIT);
    await ESTABLISH_GOAL(who, await META_LOC(CORPSE), true);
    return true;
  } else {
    return false;
  }
}

async function I_POLICE_ARRIVE() {
  move(DETECTIVE, CIRCLE);
  move(DUFFY, CIRCLE);
  move(POLICE_CAR, CIRCLE);
  await ESTABLISH_GOAL(DETECTIVE, PORCH);
  await ESTABLISH_GOAL(DUFFY, PORCH);
  if (g.HERE == PORCH || g.HERE == CIRCLE) {
    tell("Up the driveway speeds an unmarked police car with a detachable bubble light blinking on its roof. It parks right in front of you in the circle. The driver and a passenger emerge. The driver is wearing a rain slicker under which you can see a uniform. The passenger is in plain clothes, wearing a trenchcoat.\n");
    return true;
  } else {
    tell("You hear the sound of a police siren approaching. It stops.\n");
    return true;
  }
}

async function I_AMBULANCE() {
  let l = (await META_LOC(CORPSE));
  if (!g.DETECTIVE_BEEN_TO_OFFICE$) {
    await NEW_SCRIPT(DETECTIVE, g.DETECTIVE_SCRIPT);
    await NEW_SCRIPT(DUFFY, g.DUFFY_SCRIPT);
  } else {
    await GOALS$(DETECTIVE, true);
    if (!(loc(DUFFY) == POLICE_LAB)) {
      await GOALS$(DUFFY, true);
    }
  }
  clearFlag(ROPE, NDESCBIT);
  remove(CORPSE);
  if ((g.HERE == l) || (g.HERE == CIRCLE || g.HERE == PORCH || g.HERE == HALL)) {
    tell("The ambulance has finally arrived, and the attendants remove the body on a stretcher.\n");
    return true;
  } else {
    return false;
  }
}

