async function FIND_NOT_HERE(tbl, prso$) {
  let m_f = 0, obj = 0, cnt = 0, pb$ = 0, local = 0;
  m_f = await MOBY_FIND(tbl);
  if (m_f > 1) {
    pb$ = await IN_BALLROOM$(PLAYER);
    loop1: for (;;) {
      if ((cnt = cnt + 1) > m_f) {
        break loop1;
      }
      obj = get(tbl, cnt);
      if ((pb$ && (await IN_BALLROOM$(obj))) || (await CORRIDOR_LOOK(obj))) {
        if ((local = local + 1) > 1) {
          break loop1;
        } else {
          g.P_MOBY_FOUND = obj;
        }
      }
    }
    if (local == 1) {
      m_f = 1;
    }
  }
  if (m_f == 1) {
    if (prso$) {
      g.PRSO = g.P_MOBY_FOUND;
    } else {
      g.PRSI = g.P_MOBY_FOUND;
    }
    return false;
  } else if (m_f > 1) {
    if (isVerb(V.EXAMINE)) {
      return NOT_HERE_OBJECT;
    } else if (obj = await apply(getProp(obj = get(tbl, 1), P.GENERIC), obj)) {
      if (obj == NOT_HERE_OBJECT) {
        return true;
      } else if (prso$) {
        return g.PRSO = obj;
      } else {
        return g.PRSI = obj;
      }
    } else if (!g.P_NAM) {
      await TELL_NO_NOUNS();
      return true;
    } else {
      await WHICH_PRINT(0, m_f, tbl);
      g.P_ACLAUSE = tbl == g.P_PRSO ? P_NC1 : P_NC2;
      g.P_AADJ = g.P_ADJ;
      g.P_ANAM = g.P_NAM;
      await ORPHAN(false, false);
      g.P_OFLAG = true;
      return true;
    }
  } else if ((!prso$ && hasFlag(g.PRSO, PERSON) && isVerb(V.ASK_ABOUT, V.ASK_FOR, V.TELL_ME, V.WHAT_IS_WAS)) || (prso$ && isVerb(V.ASK_CONTEXT_ABOUT, V.ASK_CONTEXT_FOR)) || (!(g.WINNER == PLAYER) && isVerb(V.WALK_TO, V.FOLLOW, V.FIND, V.WHAT, V.GIVE, V.SGIVE))) {
    if (!(g.WINNER == PLAYER)) {
      await DPRINT(g.WINNER, true);
    } else if (isVerb(V.ASK_ABOUT, V.ASK_FOR, V.TELL_ME) && !(g.PRSO == PLAYER || g.PRSO == CORPSE)) {
      await DPRINT(g.PRSO, true);
    } else {
      await TELL_ISNT_ANYONE();
      return true;
    }
    tell(" looks confused. ");
    (await I_DONT_KNOW_ABOUT("any", false));
    await NOT_HERE_PRINT();
    tell("!\"\n");
    return true;
  } else if (!prso$) {
    tell("You wouldn't find any");
    await NOT_HERE_PRINT();
    tell(" there.\n");
    return true;
  } else {
    return NOT_HERE_OBJECT;
  }
}

async function NOT_HERE_PRINT() {
  if (g.P_OFLAG || g.P_MERGED) {
    if (g.P_XADJ) {
      tell(" ");
      printB(g.P_XADJN);
    }
    if (g.P_XNAM) {
      tell(" ");
      return printB(g.P_XNAM);
    } else {
      return false;
    }
  } else if (g.PRSO == NOT_HERE_OBJECT) {
    return await BUFFER_PRINT(get(g.P_ITBL, P_NC1), get(g.P_ITBL, P_NC1L), false);
  } else {
    return await BUFFER_PRINT(get(g.P_ITBL, P_NC2), get(g.P_ITBL, P_NC2L), false);
  }
}

