async function WEATHER_F() {
  if (isVerb(V.EXAMINE, V.FIND, V.LISTEN)) {
    if (!(await OUTSIDE$(g.HERE)) && !(await GLOBAL_IN$(WINDOW, g.HERE))) {
      return (await TELL_YOU_CANT("see the outside from here"));
    } else if (g.PRESENT_TIME < 550) {
      tell("The rain is pouring down. It's a great night for ducks!\n");
      return true;
    } else if (g.PRESENT_TIME < 570) {
      g.SAW_RAIN_SLACK_OFF$ = true;
      tell("The rain has slacked off, it's just a drizzle now.\n");
      return true;
    } else if (g.PRESENT_TIME < 630) {
      tell("The rain is coming down in buckets");
      if (g.SAW_RAIN_SLACK_OFF$) {
        tell(" again");
      }
      tell(".\n");
      return true;
    } else {
      tell("The rain is almost stopped, and the storm seems to be passing off to the northeast.\n");
      return true;
    }
  } else if (isVerb(V.RUB)) {
    if (await OUTSIDE$(g.HERE)) {
      tell("It's wet.\n");
      return true;
    } else {
      return (await TELL_YOU_CANT("touch that"));
    }
  } else {
    return false;
  }
}

